INSERT INTO investors (name, fund, stage, priority, category, contact, intro, next_action, next_date, notes, ticket_size, why_fit, conflict_check, fund_stage) VALUES
('Shapat (Partner)', 'White Whale Ventures', 'In Dialogue', 'P1', 'VC — Warm', 'shapat@whitewhale.vc', 'Follow up on existing thread', 'Send detailed deck + MIS this week. Ask for next meeting.', '2026-03-20', 'Warm conversation already started. Shapat has hospitality background and showed active interest. Asked for more details. Warmest live VC lead. Most important live conversation — do NOT let this go cold.', '5–20 Cr', 'Warm conversation already started. Hospitality background, active interest.', '✅ None', 'Seed / Series A'),
('Partner (name TBC)', 'TDV Partners', 'In Dialogue', 'P1', 'VC — Warm', 'Through existing contact', 'Send MIS immediately', 'Send clean MIS this week. Follow up in 5 days.', '2026-03-20', '1 meeting done. Asked for MIS — positive diligence signal. They understand ops-heavy businesses. MIS request = genuine interest. Clean P&L, occupancy, unit economics.', '5–15 Cr', '1 meeting done. Asked for MIS — positive diligence signal.', '✅ None', 'Seed / Series A'),
('Arjun Vaidya', 'V3 Ventures / Verlinvest India', 'Identified', 'P1', 'Angel', 'linkedin.com/in/arjunvaidya · cal.com/arjun-vaidya-lec0j0', 'LinkedIn DM — he says "DM me, happy to chat"', 'Send personalised LinkedIn DM this week. Lead with NUMA/Verlinvest angle.', '2026-03-20', 'Most strategic angel. Runs V3 Ventures = Verlinvest India arm. Verlinvest backed NUMA (European KiwiStays). L Catterton hospitality background. 80+ portfolio cos. Last investment Dec 2025. Unlocks BOTH angel capital AND Verlinvest VC path.', '1–3 Cr', 'Runs V3 Ventures = Verlinvest India. Backed NUMA (European KiwiStays). Highest leverage move.', '✅ None', 'Angel'),
('Neetan Chopra', 'IndiGo Ventures', 'Identified', 'P1', 'CVC — Travel Mandate', 'GoIndiGoVentures.com · Neetan Chopra on LinkedIn', 'Website + direct outreach to Neetan Chopra', 'Draft pitch around IndiGo passenger journey → KiwiStays stays. Apply on website AND email Neetan.', '2026-03-21', 'EXPLICIT mandate: travel + hospitality. ₹450Cr fund closed Jul 2025. 2 investments made — huge dry powder. IndiGo passengers fly to Goa/Dehradun and stay at KiwiStays. Distribution upside = massive. BIGGEST MISS found in research.', '5–20 Cr', 'Only fund with explicit hospitality mandate + fresh capital. Distribution partnership upside.', '✅ None', 'Series A');
INSERT INTO investors (name, fund, stage, priority, category, contact, intro, next_action, next_date, notes, ticket_size, why_fit, conflict_check, fund_stage) VALUES
('Rishabh Mariwala', 'Sharrp Ventures', 'Identified', 'P2', 'Family Office', 'sharrpventures.com/pitch · Rishabh Mariwala LinkedIn', 'Public pitch form + LinkedIn', 'Submit pitch form AND DM Rishabh on LinkedIn with 3-line hook.', '2026-03-22', 'Marico family office. Portfolio: Mamaearth, boAt, SleepyCat, Bira, mCaffeine. COO of Sula Vineyards is now partner. 3 investments in last 12 months. Patient capital, no VC lifecycle pressure.', '5–20 Cr', 'Premium Indian consumer brand thesis = KiwiStays. Patient capital.', '✅ None', 'Seed / Series A'),
('Vikram Vaidyanathan', 'Z47 (formerly Matrix Partners India)', 'Identified', 'P2', 'VC — Consumer Brand', 'namaste@z47.com · z47.com · Vikram LinkedIn', 'Email namaste@z47.com + LinkedIn to Vikram', 'Lead with Stanza Living parallel. Email + LinkedIn.', '2026-03-22', 'Backed Stanza Living at seed — managed accommodation, ops-heavy, exact model DNA. Also backed Country Delight, DaMENSCH. Fund IV = ₹4,500 Cr. Very founder-friendly culture.', '5–25 Cr', 'Backed Stanza Living (managed accommodation). Exact model DNA as KiwiStays.', '✅ None', 'Series A'),
('Abhay Pandey / Gautam Mago', 'A91 Partners', 'Identified', 'P2', 'VC — Consumer Growth', 'a91partners.com · Abhay Pandey LinkedIn', 'LinkedIn to deal leads who worked Blue Tokai', 'Find who led Blue Tokai deal at A91 — that person is the door. Lead with "Blue Tokai of hospitality."', '2026-03-23', 'Backed Blue Tokai (ops-heavy premium offline brand), Spacewood, Atomberg. $665M Fund III closed Apr 2025. May need stronger revenue first but worth planting seed now.', '15–40 Cr', 'Blue Tokai lead = ops-heavy premium offline brand thesis. $665M fresh fund.', '✅ None', 'Series A / B'),
('Hariharan Premkumar', 'Anicut Capital', 'Identified', 'P2', 'VC — Consumer Brand', 'anicuts.com · Hariharan LinkedIn', 'Direct application + LinkedIn', 'Apply directly via website AND LinkedIn. Lead with Blue Tokai/managed-ops thesis.', '2026-03-22', 'Co-invested Blue Tokai Series B AND C. Consumer brand focus. Chennai-based, less gatekept. Clear submission process. More accessible than A91.', '5–20 Cr', 'Co-invested Blue Tokai = gets premium offline consumer brands.', '✅ None', 'Seed / Series A'),
('Gaurav Burman', 'Burman Family Holdings', 'Identified', 'P2', 'Family Office', 'Gaurav Burman LinkedIn · burmanfamilyholdings.com', 'LinkedIn direct to Gaurav Burman', 'Lead with Isprava angle: supply side → management layer.', '2026-03-23', 'Dabur family investment arm. Backed Isprava (luxury second homes in Goa/Alibaug) at $130M growth round. RISK: Isprava owns Lohono Stays which is a DIRECT managed villa competitor.', '3–15 Cr', 'Backed Isprava — knows luxury Goa villas from developer side. KiwiStays = management layer.', '⚠️ RISKY — Isprava owns Lohono Stays (direct managed villa competitor)', 'Seed / Series A'),
('Arjun Vaidya → Lopo Champalimaud', 'Verlinvest / V3 Ventures', 'Identified', 'P2', 'VC — International', 'v3.ventures · verlinvest.com', 'Via Arjun Vaidya angel relationship first', 'DO NOT cold email Verlinvest. Get Arjun Vaidya on board first — he becomes internal champion.', '2026-03-25', 'Backed NUMA (European managed apartment startup — identical model). Backed Blue Tokai. India arm = V3 Ventures. Two-stage strategy: Arjun angel first → institutional Verlinvest round.', '10–30 Cr', 'NUMA = KiwiStays. Once Arjun is in, institutional round becomes very possible.', '✅ None', 'Series A'),
('Mayank Jain / Alok Goyal', 'Stellaris Venture Partners', 'Identified', 'P2', 'VC — Consumer Tech', 'stellarisvp.com · Mayank Jain LinkedIn', 'Apply via website + LinkedIn to Mayank Jain', 'Lead with Peeko parallel: fragmented, trust deficit, offline-first. DM Mayank Jain.', '2026-03-22', 'Led Peeko seed (Aug 2025) — ops-heavy, fragmented market. Backed Mamaearth, Zouk, Nestasia. $300M Fund III closed Nov 2024. Mayank''s thesis = identical to managed vacation rentals.', '3–15 Cr', 'Peeko thesis (fragmented, unbranded, attractive margins) = identical to KiwiStays.', '✅ None', 'Seed / Series A'),
('Maninder Gulati', 'Angel (ex-OYO CSO)', 'Identified', 'P2', 'Angel', 'Maninder Gulati LinkedIn', 'LinkedIn DM — reachable post-Peeko visibility', 'Lead with OYO angle: strategy for largest managed hospitality → KiwiStays taking it premium. Ask for 20 mins.', '2026-03-22', 'Built strategy at OYO — knows managed accommodation, property owner dynamics intimately. Just backed Peeko (Aug 2025) — actively deploying. His backing = signal to property owners.', '1–3 Cr', 'Ex-OYO CSO. Knows managed hospitality better than any angel. Credibility signal.', '✅ None', 'Angel'),
('Mukesh Bansal', 'Angel (Myntra / Cult.fit)', 'Identified', 'P2', 'Angel', 'Mukesh Bansal LinkedIn', 'LinkedIn DM', 'Lead with Cult.fit parallel: offline, premium, experience-led, ops-heavy. Ask for 20 mins.', '2026-03-22', 'Built Cult.fit — offline, ops-heavy, premium consumer experience across 200+ centres. Exact DNA match. Co-invests with Arjun Vaidya frequently. Backed FirstClub (Dec 2024) — actively writing cheques.', '1–3 Cr', 'Cult.fit = strongest operational parallel. Offline, premium, experience-led, ops-heavy.', '✅ None', 'Angel'),
('Neil Bahal', 'Negen Capital / Negen Angel Fund', 'Identified', 'P2', 'Angel Fund — Consumer', 'negenaif.com · Neil Bahal LinkedIn', 'LinkedIn DM + Negen Angel Fund application', 'Lead with Blue Tokai parallel — he backed Blue Tokai AND Burma Burma.', '2026-04-02', 'Founder of Negen Capital (PMS) + Negen Angel Fund (AIF). Portfolio: Blue Tokai, Burma Burma, Burger Singh. Thesis: tech-enabled, consumer-facing brands. STRONGEST thesis match among angel funds.', '1–5 Cr', 'Blue Tokai + Burma Burma in portfolio = already believes in premium offline consumer brands with ops complexity.', '✅ None', 'Seed / Pre-Series A'),
('V3 Ventures Team', 'V3 Ventures (Hosteller investor)', 'Identified', 'P2', 'VC — Hospitality', 'v3.ventures', 'Via Arjun Vaidya angel relationship', 'NOTE: V3 led Hosteller Series A. Approach via Arjun Vaidya path.', '2026-03-22', 'Led The Hosteller Series A (₹32Cr equity, Sep 2024). V3 = Verlinvest India arm run by Arjun Vaidya. Hosteller = budget backpacker hostels. KiwiStays = premium villas. Different segments but same managed-stays thesis.', '5–20 Cr', 'Led Hosteller Series A + backed NUMA. Deepest hospitality thesis of any VC.', '⚠️ Hosteller in portfolio — budget segment. Must clearly articulate premium differentiation.', 'Seed / Series A');
INSERT INTO investors (name, fund, stage, priority, category, contact, intro, next_action, next_date, notes, ticket_size, why_fit, conflict_check, fund_stage) VALUES
('Varun Alagh', 'Angel (Mamaearth / Honasa)', 'Identified', 'P3', 'Angel', 'Varun Alagh LinkedIn', 'LinkedIn — active and reachable', 'Short message. Lead with: ops-heavy premium consumer brand, 85 properties, profitable. Ask for 20 mins.', '2026-03-25', '73 portfolio companies. Last investment Feb 2026 — most actively deploying capital. Built Mamaearth = ops-heavy premium consumer brand at scale.', '1–3 Cr', 'Most actively deploying. Feb 2026 = writing cheques right now.', '✅ None', 'Angel'),
('Aman Gupta', 'Angel (boAt / Offbeat Studios)', 'Identified', 'P3', 'Angel', '@boatxaman on Instagram', 'Instagram DM @boatxaman', 'Lead with Offbeat Studios: "You''re building in travel. We manage what your audience stays in."', '2026-03-25', 'Building Offbeat Studios = travel/content company. 11 investments in last 12 months. Backs lifestyle consumer brands. Instagram DM works — he responds to founders.', '1–3 Cr', 'Offbeat Studios = travel/content. More than generic angel pitch.', '✅ None', 'Angel'),
('Padmaja Ruparel', 'Indian Angel Network (IAN)', 'Identified', 'P3', 'Angel Platform', 'indianangelnetwork.com · Padmaja Ruparel LinkedIn', 'Apply at indianangelnetwork.com', 'Apply formally. Ask to connect with hospitality-focused member angels.', '2026-03-24', 'Explicitly lists HOSPITALITY as investment sector. Backed Brevistay. IAN Alpha Fund closed at $100M Dec 2025 — fresh capital. 22 investments in 2025.', '3–8 Cr (assembled)', 'Only platform with genuine hospitality thesis.', '✅ None', 'Seed'),
('Nandini Mansinghka', 'Mumbai Angels', 'Identified', 'P3', 'Angel Platform', 'mumbaiangels.net', 'Apply via mumbaiangels.net', 'Apply, then request intro to members with travel/hospitality background.', '2026-03-26', '700+ HNI investors across 60 cities. Premium consumer portfolio (Vahdam, Purplle, Fitpass). HNI member base likely includes Goa property owners. Slower process (60–90 days) but premium base.', '5–15 Cr (assembled)', 'Premium HNI base. Some members are likely KiwiStays property owner profile.', '✅ None', 'Seed'),
('Kanwaljit Singh / Vinay Singh', 'Fireside Ventures', 'Identified', 'P3', 'VC — Consumer', 'firesideventures.com · Kanwaljit Singh LinkedIn', 'Apply at firesideventures.com', 'Pitch as "India''s first premium travel experience brand." Expect "not our model" pushback.', '2026-03-26', 'India''s largest pure consumer brand fund. ₹5,300 Cr AUM. Fund IV just closed. Backed Escape Plan (travel accessories). CAVEAT: entire portfolio is product brands.', '5–20 Cr', 'Largest consumer brand fund. But potential model mismatch — service vs product.', '⚠️ Check', 'Series A'),
('GC India Team', 'General Catalyst India', 'Identified', 'P3', 'VC — Global / India', 'generalcatalyst.com', 'Apply via generalcatalyst.com/india', 'Lead with Pronto parallel: formalising offline domestic services → premium vacation rentals.', '2026-03-27', 'Committed $5Bn to India. Backed Pronto (ops-heavy offline home services — exact same thesis). India arm = ex-Venture Highway team. GC globally is tech/AI first but Pronto shows India team will back ops-heavy plays.', '5–25 Cr', 'Backed Pronto = formalising India offline services market. $5Bn India commitment.', '✅ None', 'Series A'),
('Partners (Mumbai-based)', 'Epiq Capital', 'Identified', 'P3', 'VC — India Growth', 'epiqcapital.com', 'Apply via epiqcapital.com + LinkedIn', 'Lead with Pronto Series B. BUT: typically enter at Series B. Keep warm for next round.', '2026-03-28', 'Led Pronto $25M Series B (Mar 2026). Portfolio: Zepto, Lenskart, Cult.fit. Also backed GIVA (offline premium jewellery). Typically invest $10-20M at Series B stage.', '10–25 Cr', 'Led Pronto Series B. Same thesis. But typically Series B entry.', '✅ None', 'Series B'),
('Binny Bansal', 'Angel (Flipkart Co-founder)', 'Identified', 'P3', 'Angel', 'Binny Bansal LinkedIn', 'LinkedIn — moderately accessible', 'Lower priority than Mukesh/Maninder. Approach after Tier 1-2 anchors confirmed.', '2026-03-28', 'Backed FirstClub (Dec 2024 seed). 9 investments in past 12 months — actively deploying. Less direct thesis fit but strong credibility signal on cap table.', '1–3 Cr', 'Cap table credibility signal to VCs. Not thesis-driven but adds credibility.', '✅ None', 'Angel'),
('Abhishek Goyal', 'Angel (Tracxn Co-founder)', 'Identified', 'P3', 'Angel', 'Abhishek Goyal LinkedIn', 'LinkedIn', 'Lower priority. Approach only if round has remaining capacity.', '2026-04-01', 'Backed Peeko seed (Aug 2025). Data and SaaS background primarily. Less thesis fit but active angel. Network angel — useful for intros.', '0.5–1 Cr', 'Network angel. Useful for introductions more than conviction capital.', '✅ None', 'Angel'),
('Karthik Reddy / Sajith Pai', 'Blume Ventures', 'Identified', 'P3', 'VC — Early Stage', 'blume.vc · Karthik Reddy LinkedIn', 'Email + LinkedIn', 'Lead with goSTOPS parallel — they led goSTOPS Series A (₹35Cr, Mar 2025). Prove KiwiStays is premium version.', '2026-03-25', 'Led goSTOPS Series A (₹35Cr, Mar 2025) — micro-hospitality, asset-light, travel. Also early Zostel backer. India-first thesis. Strongest VC signal from India hospitality space.', '2–10 Cr', 'Led goSTOPS Series A. Already has hospitality thesis.', '⚠️ goSTOPS portfolio — budget hostel, NOT premium villa. No direct conflict but discuss positioning.', 'Seed / Series A'),
('Sanjay Mehta / Sumesh Menon', 'Lead Angels Network', 'Identified', 'P3', 'Angel Platform', 'leadangels.in', 'Apply via leadangels.in', 'Apply. Mention goSTOPS success as thesis validation for managed stays category.', '2026-03-27', 'Mumbai-based angel network. Invested in goSTOPS pre-Series A AND Series A. Travel thesis proven. IIT Bombay alumni-driven.', '1–5 Cr (assembled)', 'Invested in goSTOPS across rounds. Proven travel/hospitality thesis.', '⚠️ goSTOPS in portfolio — budget, not premium. Discuss differentiation.', 'Seed'),
('Nikhil Kamath / Abhijeet Pai', 'Gruhas Capital', 'Identified', 'P3', 'VC — PropTech/Consumer', 'gruhas.com', 'Apply via gruhas.com + LinkedIn', 'Position as PropTech + consumer experience play.', '2026-03-28', 'Co-founded by Nikhil Kamath (Zerodha). $650M+ AUM across PropTech and consumer funds. Earth Fund (₹300Cr) = proptech/sustainability. 63 investments in 5 years.', '3–15 Cr', 'PropTech + consumer crossover. Nikhil Kamath = massive signal value on cap table.', '✅ None', 'Pre-Series A / Series A'),
('T.V. Mohandas Pai', 'Aarin Capital', 'Identified', 'P3', 'VC — Multi-sector', 'aarincapital.com', 'Apply via website + LinkedIn', 'Position around hospitality vertical (4% of their portfolio).', '2026-03-28', 'Bangalore-based fund led by TV Mohandas Pai (ex-Infosys CFO). Dedicated hospitality vertical though small. 18 consumer investments. 40+ total portfolio.', '3–10 Cr', 'Has dedicated hospitality vertical. 18 consumer investments.', '✅ None', 'Seed / Series A'),
('Aryaman Vikram Birla', 'Aditya Birla Ventures', 'Identified', 'P3', 'CVC — Consumer/Hospitality', 'adityabirlaventures.com · Aryaman Vikram Birla LinkedIn', 'Apply via adityabirlaventures.com + LinkedIn to Aryaman', 'Position as consumer brand in hospitality.', '2026-04-05', 'Founded by Aryaman Vikram Birla (Kumar Mangalam Birla''s son). Portfolio: Mokobara, Giva, Eka.Care. Also runs ABNAH — operates Hakkasan, Yauatcha.', '3–15 Cr', 'Aryaman runs both a consumer VC fund AND a hospitality operating company.', '✅ None', 'Pre-Series A / Series A');
INSERT INTO investors (name, fund, stage, priority, category, contact, intro, next_action, next_date, notes, ticket_size, why_fit, conflict_check, fund_stage) VALUES
('Sumir Chadha / Sandeep Singhal', 'WestBridge Capital', 'Identified', 'P4', 'VC — Growth PE', 'westbridge.vc', 'Warm intro only at this stage', 'Plant seed by sharing updates. Reach at Series B.', '2026-04-15', 'Backed Third Wave Coffee Series B + C. Deep consumer conviction. Typical cheque = $20–50M+. Too large for current round.', '50–150 Cr', 'Deep consumer conviction. But cheque too large for current round.', '✅ None', 'Series B+'),
